	using namespace noarr;

#pragma scop
	// ---------------------------------------------------------------------
	// Phase 1: tmp[i][j] = alpha * sum_k A[i][k] * B[k][j]
	// ---------------------------------------------------------------------

	// 1a) Explicitly zero tmp once.
	//     This is equivalent to the original "tmp[i][j] = 0" inside the
	//     (i,j) loops, but gives a simple, vectorizable pass.
	traverser(tmp).for_each([&](auto s) {
		tmp[s] = (num_t)0;
	});

	// 1b) Matrix multiplication with layout-aware ordering:
	//     outer:  i  (rows of A / tmp)
	//     middle: k  (shared dimension)
	//     inner:  j  (columns, contiguous in both B and tmp)
	traverser(tmp, A, B).template for_dims<'i'>([&](auto trav_i) {
		// 'i' fixed here
		trav_i.template for_dims<'k'>([&](auto trav_ik) {
			// 'i' and 'k' fixed here

			// A[i,k] is reused across all j for this (i,k)
			const num_t a_ik = A[trav_ik];
			const num_t scaled_a_ik = alpha * a_ik;

			// iterate over j (inner, contiguous for tmp and B)
			trav_ik.template for_dims<'j'>([&](auto trav_ijk) {
				tmp[trav_ijk] += scaled_a_ik * B[trav_ijk];
			});
		});
	});

	// ---------------------------------------------------------------------
	// Phase 2: D[i][l] = beta * D[i][l] + sum_j tmp[i][j] * C[j][l]
	// ---------------------------------------------------------------------

	// 2a) Scale D by beta once, outside of the j-loop.
	//     For each element this keeps the operation order:
	//       D[i,l] <- beta * D[i,l];
	//       then additions over j.
	traverser(D).for_each([&](auto s) {
		D[s] *= beta;
	});

	// 2b) Accumulate tmp * C into D with i–j–l ordering:
	//       inner:  l  (columns of D and C, contiguous)
	//       middle: j  (rows of C)
	//       outer:  i  (rows of D and tmp)
	traverser(D, tmp, C).template for_dims<'i'>([&](auto trav_i) {
		// 'i' fixed here
		trav_i.template for_dims<'j'>([&](auto trav_ij) {
			// 'i' and 'j' fixed here

			// tmp[i,j] is reused across all l for this (i,j)
			const num_t t_ij = tmp[trav_ij];

			// iterate over l (inner, contiguous for D and C)
			trav_ij.template for_dims<'l'>([&](auto trav_ijl) {
				D[trav_ijl] += t_ij * C[trav_ijl];
			});
		});
	});
#pragma endscop
}

} // namespace

int main(int argc, char *argv[]) {
	using namespace std::string_literals;

	// problem sizes
	std::size_t ni = NI;
	std::size_t nj = NJ;
	std::size_t nk = NK;
	std::size_t nl = NL;

	// scalars
	num_t alpha;
	num_t beta;

	// set all potential lengths once; each layout will use the relevant ones
	auto set_lengths =
		noarr::set_length<'i'>(ni) ^
		noarr::set_length<'j'>(nj) ^
		noarr::set_length<'k'>(nk) ^
		noarr::set_length<'l'>(nl);

